Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <iomanip>
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    uint64_t p, k;
    std::cin >> p >> k;

    const uint64_t Mod = 1000000007;

    auto FastPow = [&](uint64_t a, uint64_t p) {
        uint64_t res = 1;
        uint64_t base = a % Mod;
        while (p > 0) {
            if (p & 1) res = (res * base) % Mod;
            base = (base * base) % Mod;
            p >>= 1;
        }
        return res;
    };

    if (k == 0) {
        std::cout << FastPow(p, p - 1) << std::endl;
        return 0;
    }
    if (k == 1) {
        std::cout << FastPow(p, p) << std::endl;
        return 0;
    }

    std::vector<bool> used(p + 1, false);
    uint64_t ans = 1;
    uint64_t groups = 0;

    for (uint64_t x = 1; x < p; ++x) {
        if (used[x]) continue;
        groups++;
        ans = (ans * p) % Mod;
        uint64_t v = x;
        while (!used[(v * k) % p]) {
            used[(v * k) % p] = true;
            v = (v * k) % p;
        }
    }
    std::cout << ans << std::endl;
    return 0;
}
